import { ChangeDetectionStrategy, Component, computed, signal } from '@angular/core';

type Item = { id: string; label: string };

@Component({
  selector: 'app-root',
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {
  readonly topItems = signal<Item[]>([
    { id: 'a', label: 'Alpha' },
    { id: 'b', label: 'Beta' },
    { id: 'c', label: 'Gamma' },
    { id: 'd', label: 'Delta' },
    { id: 'e', label: 'Epsilon' }
  ]);

  readonly bottomItems = signal<Item[]>([
    { id: 'x', label: 'Xenon' },
    { id: 'y', label: 'Yttrium' },
    { id: 'z', label: 'Zinc' }
  ]);

  readonly topSelected = signal<ReadonlySet<string>>(new Set());
  readonly bottomSelected = signal<ReadonlySet<string>>(new Set());

  readonly canMoveDown = computed(() => this.topSelected().size > 0);
  readonly canMoveUp = computed(() => this.bottomSelected().size > 0);

  isTopSelected(id: string): boolean {
    return this.topSelected().has(id);
  }

  isBottomSelected(id: string): boolean {
    return this.bottomSelected().has(id);
  }

  toggleTop(id: string, checked: boolean): void {
    this.topSelected.update((selected) => toggled(selected, id, checked));
  }

  toggleBottom(id: string, checked: boolean): void {
    this.bottomSelected.update((selected) => toggled(selected, id, checked));
  }

  moveDown(): void {
    if (!this.canMoveDown()) {
      return;
    }

    const { moved, remaining } = split(this.topItems(), this.topSelected());
    this.topItems.set(remaining);
    this.bottomItems.update((items) => [...items, ...moved]);
    this.topSelected.set(new Set());
  }

  moveUp(): void {
    if (!this.canMoveUp()) {
      return;
    }

    const { moved, remaining } = split(this.bottomItems(), this.bottomSelected());
    this.bottomItems.set(remaining);
    this.topItems.update((items) => [...items, ...moved]);
    this.bottomSelected.set(new Set());
  }
}

// Copy the Set: add or delete on the one the signal holds keeps its reference, and the signal would not notify.
function toggled(selected: ReadonlySet<string>, id: string, checked: boolean): ReadonlySet<string> {
  const next = new Set(selected);
  if (checked) {
    next.add(id);
  } else {
    next.delete(id);
  }
  return next;
}

// Both parts keep the source order, so moved items arrive in list order rather than in the order they were checked.
function split(items: Item[], selected: ReadonlySet<string>): { moved: Item[]; remaining: Item[] } {
  return {
    moved: items.filter((item) => selected.has(item.id)),
    remaining: items.filter((item) => !selected.has(item.id))
  };
}
